bool handle_valid(const uint8_t *h) {
    uint8_t *const *object = get<uint8_t **>(h, 0);
    const uint32_t id = get<uint32_t>(h, 8);
    return object && id && *object && get<uint32_t>(*object, 0x7c) == id;
}












