uint8_t *u3x_rp_h(const uint8_t *handle);
uint8_t *u3x_rp_trk(uintptr_t base, uint32_t index);
int u3x_rp_dead(const uint8_t *tracker);
uint8_t *u3x_rp_trk_by_id(uintptr_t base, uint32_t net_id);
